const url = "https://github.com/alexey1312/reachy-mini-swift/raw/19c9f1fa/docs/media/demo.mp4";
const violations = [];
document.addEventListener('securitypolicyviolation', e => violations.push(e.blockedURI + ' :: ' + e.violatedDirective));
const v = document.createElement('video');
v.preload = 'metadata';
v.style.position = 'fixed'; v.style.left = '-9999px';
const outcome = await new Promise(res => {
  const t = setTimeout(() => res('timeout'), 15000);
  v.onloadedmetadata = () => { clearTimeout(t); res(`loaded ${v.videoWidth}x${v.videoHeight} ${Math.round(v.duration)}s`); };
  v.onerror = () => { clearTimeout(t); res(`error code=${v.error && v.error.code} ${v.error && v.error.message}`); };
  v.src = url;
  document.body.appendChild(v);
});
v.remove();
JSON.stringify({ outcome, violations });

const urls = [
  "https://github.com/alexey1312/reachy-mini-swift/raw/19c9f1fa/docs/media/demo.mp4",
  "https://github.com/alexey1312/reachy-mini-swift/raw/refs/heads/docs/demo-video/docs/media/demo.mp4"
];
const out = [];
for (const u of urls) {
  try {
    const r = await fetch(u, { headers: { Range: 'bytes=0-1023' } });
    out.push({ u: u.slice(50), status: r.status, type: r.headers.get('content-type'), len: r.headers.get('content-length'), redirected: r.redirected, final: r.url.slice(0, 60) });
  } catch (e) { out.push({ u: u.slice(50), err: String(e) }); }
}
JSON.stringify(out, null, 1);

const v = document.createElement('video');
v.preload = 'auto'; v.muted = true;
v.style.position='fixed'; v.style.left='-9999px';
v.src = "https://github.com/alexey1312/reachy-mini-swift/raw/19c9f1fa/docs/media/demo.mp4";
document.body.appendChild(v);
const res = await new Promise(r => {
  const t = setTimeout(() => r({ verdict: 'no playable metadata after 25s', networkState: v.networkState, readyState: v.readyState, err: v.error && v.error.code }), 25000);
  v.onloadedmetadata = () => { clearTimeout(t); r({ verdict: 'PLAYS', dims: `${v.videoWidth}x${v.videoHeight}` }); };
  v.onerror = () => { clearTimeout(t); r({ verdict: 'ERROR', code: v.error && v.error.code, msg: v.error && v.error.message }); };
});
v.remove();
JSON.stringify(res);
